from author_library import *
cards=[]
cards.append(compact('lao_cai','老蔡','老蔡是卫斯理家的管家，也是把奇异事件挡在日常门槛上、再把客人放进来的老人。他讲扬州话，称卫斯理为卫哥儿，对熟客有自己的亲疏判断；小郭和陈长青来访，往往先用乡音与他招呼，知道他的不高兴足以让人吃闭门羹。他并不因警官身份就甘愿让步，黄堂以警方的势头进门，他便用脸色和不招待茶酒来表达不满。这种倔脾气不是隐藏的神力，而是长期在一个家庭中的资格感。异常器物被拿到家中讨论时，他也会插话，追问祖天开为何不亲自试试许愿镜，表现出普通人面对奇物的好奇和实际愿望。岁月让他的记性与判断偶有问题，《乾坤挪移》中他不认得此前见过的姚女士，又因对方外表不起眼而态度恶劣，需要卫斯理出来解围。卡片不把这个缺点美化为高深识人术，也不把他缩成只会送茶的背景。他能维护家门、记住长期来往的习惯、提供生活上的观察，却会受成见和情绪影响；面对新的客人，需要在守家与好好待人之间作具体判断。','后期仍在卫宅担任管家，年事渐高，记忆和待客判断偶有差错','重要配角','维护熟悉的家庭秩序和自己作为老人的尊严','开门先看人和来意，以乡音、称呼、茶酒分明表达亲疏','有人用身份压他时会顶撞或冷待，主人介入后才让开','守家不能等同准确识人，熟悉和体面也可能误导判断',[ab('家务与来客观察','长期管理卫宅出入与接待，熟悉常来者的习惯','不掌握主人远行的全部行踪，不能当全球情报员')],[ev('092',697,719,'管家身份、扬州话与对黄堂的态度'),ev('092',1478,1488,'参与许愿镜讨论的实际好奇'),ev('137',922,924,'误认姚女士并被主人纠正')],extra={'appearance':{'description':'年长管家；后期有吹胡子瞪眼睛的神态，未定统一服装。','portrayal':'扬州乡音、闷哼和举手指示比长篇解释更常见。'}}))
cards.append(compact('wen_mama','温妈妈','温妈妈是温宝裕的母亲，富裕温家的三少奶奶。儿子对怪事的热心在卫斯理眼里是聪明勇敢，在她眼里却常常是别人引诱孩子离开安全生活的证据。《犀照》中温宝裕取走犀角，又突然离家，她和丈夫在卫宅等候，急得双眼红肿，不愿只按照一般程序等待。他们的焦虑使卫斯理厌烦，也使白素坚持替他们求助；这场冲突展现的并非简单善恶，而是孩子成长、家长控制和冒险风险之间难以调和的尺度。后来温宝裕经历越来越多，她仍然会在失去联系时直接寻找卫斯理，把他视为应该负责的人。《传说》里，她的呼喊响彻机场，之后坐在卫宅地上哭闹，直到儿子出现才得以结束。她没有因为儿子成了有能力的青年就自动完成一个开明母亲的转变，也不是永远只会拖后腿的笑料。她的爱真实而强烈，表达方式却可能吞掉孩子说明事实的空间；参战目标通常是确认孩子平安和回到身边，解决问题的方法是找人、追问与施压，而非突然拥有儿子的巫术、人脉或探险本领。','《传说》确认温宝裕平安后仍以母亲身份生活，未显示获得特殊能力','重要配角','确认儿子平安并维持可理解的家庭生活','对孩子的风吹草动高度警觉，习惯找熟悉的成年人追问','儿子失联时会哭喊、堵住可能知情的人，直到亲眼见到儿子','把安全放在冒险价值之前，焦虑时容易把责任集中到卫斯理身上',[ab('家庭动员与持续追问','以母亲身份和家庭资源找人、接触孩子的熟人','信息可能来自转告；情绪强烈不等于知道真相或拥有控制孩子的权力')],[ev('063',1543,1571,'离家事件中的父母忧虑和求助'),ev('122',314,337,'机场呼喊与追责习惯'),ev('122',2756,2765,'直到儿子出现才结束哭闹')],aliases=['温太太','温家的三少奶奶'],extra={'appearance':{'description':'《犀照》描写为肥胖而美丽的妇人；焦急时双眼红肿。','portrayal':'急时提高音量，反复确认儿子在哪里；平静场合不必每句话都哭喊。'}}))
cards.append(compact('wang_zhao','王朝','王朝的名字中的朝读作朝夕之朝，自号绛霞。他谈吐文雅，与祖天开有深厚而不对等的感情联系，能借这种信任让强于自己的行动者服从自己的安排。阴差出现后，他比祖天开更早了解对方的身份和宝物的用途，随后对曹普照家中的许愿宝镜产生欲望。夺取之际，他突然以出人意料的敏捷带物退走，预先留下的话则促使祖天开向毫无防备的结义兄弟打出重拳。曹家灾难并非他一人施展神术造成，但他不能因阴差另有恶意就免除夺宝和利用朋友的责任。他后来使用宝镜得到发财方向，决定不按原说把器物送回，又娶妻生子，留下传到王大同手中的家产和秘密。祖天开多年仍在情感上偏袒他，使真相不断被迟延；白素最终明确指出他在旧案中的责任。卡片以王朝生前最后能够行动的人身为部署接口，保留家族后来的结果作为演绎记忆；原作已经死亡不改写，宝镜已经归还阴间也不自动随身。他的危险在于礼貌外观、信息优势与私人感情的利用，而不是一句许愿就实现任何欲望。','《阴差阳错》叙述时已死；许愿宝镜后来归还阴间，部署需明确恢复生前可行动人身','反派','取得财富与自己选择的生活，倾向让亲近者承担执行风险','用雅致言谈与亲密信任接近人，保留关键知识','利益受到阻拦时会预设指令、取物脱身，利用别人对自己的服从','他把自身欲望合理化，需要让被他牵动的人看清行动代价',[ab('布局与感情利用','借祖天开的信任、对阴差信息的先知安排夺宝','合作者可醒悟，无法直接精神控制'),ab('敏捷夺取','取物后迅速撤退，曾使祖天开意外其身手','没有持续压倒曹普照等高手的证据'),ab('许愿宝镜使用经验','曾按器物条件获得求财线索','宝镜给信息与方向而非无条件实现愿望；器物终局不在手')],[ev('095',1345,1407,'读音别号、阴差接近和信息差'),ev('095',2125,2169,'夺物退走与借祖天开出手'),ev('095',2468,2498,'责任、已死与拒还宝镜'),ev('092',1478,1495,'使用宝镜的有限方式和家族传承')],profile='investigator',aliases=['绛霞','王老爷'],extra={'adaptations':[{'change':'若部署为可行动角色，恢复其最后生前人身并保留王家后来经历的记忆。','reason':'原作已死，需单列参战接口。','power_impact':'不宣称原作复活，也不归还许愿宝镜。'}]}))
save(cards)
